_INV_CASES = json.loads(_INV_CORE_RAW)["cases"]
_INV_SELECTION = json.loads(_INV_MANIFEST_RAW)


def _inv_freeze(value):
    return tuple(_inv_freeze(v) for v in value) if type(value) is list else value


def _inv_construct(case):
    roots = {k: _inv_freeze(v) for k, v in case["input"].items()}
    traps = []

    def hit(*args, **kwargs):
        traps.append("trap")
        raise AssertionError("INV_GETTER_COERCION_TRAP")

    def change(value, path, replacement):
        if not path:
            return replacement(value)
        items = list(value)
        items[path[0]] = change(items[path[0]], path[1:], replacement)
        return tuple(items)

    for override in case["construction"]["overrides"]:
        kind = override["python_type"]
        methods = {name: hit for name in override["trap_methods"]}
        if kind == "list":
            replacement = list
        else:
            base = {"tuple_subclass": tuple, "str_subclass": str, "int_subclass": int}[kind]
            replacement = type("InventoryTrap", (base,), methods)
        path = override["path"]
        roots[path[0]] = change(roots[path[0]], path[1:], replacement)
    traps.clear()
    return roots["objects"], roots["evidence"], traps


def _inv_input_fingerprint(value):
    if type(value) in (tuple, list):
        return (type(value).__name__, tuple(_inv_input_fingerprint(x) for x in value))
    if type(value) in (str, int, bool, type(None)):
        return (type(value).__name__, value)
    return ("subclass_identity", id(value))


def _inv_plain(value):
    import dataclasses

    if dataclasses.is_dataclass(value):
        return {
            field.name: _inv_plain(getattr(value, field.name))
            for field in dataclasses.fields(value)
        }
    if type(value) is tuple:
        return [_inv_plain(x) for x in value]
    return value


def _inv_deep_immutable(value):
    import dataclasses

    if type(value) is tuple:
        for x in value:
            _inv_deep_immutable(x)
    elif dataclasses.is_dataclass(value):
        assert type(value).__module__ == "recoryn.schema"
        assert value.__dataclass_params__.frozen and not value.__dataclass_params__.repr
        assert hasattr(type(value), "__slots__") and not hasattr(value, "__dict__")
        for field in dataclasses.fields(value):
            _inv_deep_immutable(getattr(value, field.name))
    else:
        assert type(value) in (str, int, bool, type(None)), "INV_DEEP_IMMUTABLE"


def _inv_run_hand(case, monkeypatch, objects=None, evidence=None, *, original_indices=True):
    import builtins
    import ctypes
    import dataclasses
    import io
    import multiprocessing
    import os
    import socket
    import sqlite3
    import subprocess
    import threading
    from contextlib import ExitStack
    from unittest.mock import patch

    from recoryn import schema

    if objects is None:
        objects, evidence, traps = _inv_construct(case)
    else:
        traps = []
    before = _inv_input_fingerprint((objects, evidence))
    expected = case["expected"]
    matcher = schema._current_profile_candidate
    matched = []
    attempts = []

    def observe_matcher(logical):
        matched.append(logical)
        return matcher(logical)

    def forbidden(*args, **kwargs):
        attempts.append("I/O")
        raise AssertionError("INV_ACTUAL_API_IO")

    with monkeypatch.context() as scoped, ExitStack() as stack:
        scoped.setattr(schema, "_current_profile_candidate", observe_matcher)
        targets = [
            (builtins, "open"),
            (io, "open"),
            (os, "open"),
            (os, "system"),
            (sqlite3, "connect"),
            (socket, "socket"),
            (socket, "getaddrinfo"),
            (threading.Thread, "start"),
            (subprocess, "Popen"),
            (multiprocessing.process.BaseProcess, "start"),
        ]
        targets.extend(
            (ctypes, name)
            for name in ("CDLL", "PyDLL", "WinDLL", "OleDLL")
            if hasattr(ctypes, name)
        )
        for owner, name in targets:
            stack.enter_context(patch.object(owner, name, forbidden))
        # Construction and spy/trap installation are outside the actual API call.
        traps.clear()
        try:
            result = schema._project_supplied_inventory(objects, evidence)
        except ValueError as error:
            assert expected["kind"] == "ValueError", "INV_UNEXPECTED_VALUEERROR_AFTER_ACTUAL_CALL"
            assert type(error) is ValueError, "INV_EXACT_ERROR_TYPE"
            assert error.args == tuple(expected["args"]), "INV_CLOSED_ERROR_AFTER_ACTUAL_CALL"
            assert str(error) == expected["str"] and repr(error) == expected["repr"]
            result = None
        else:
            assert expected["kind"] != "ValueError", "INV_EXPECTED_ERROR_AFTER_ACTUAL_CALL"
            if expected["kind"] == "None":
                assert result is None, "INV_UNPROVEN_NONE_AFTER_ACTUAL_CALL"
            else:
                assert type(result) is schema._SuppliedInventoryProjection, (
                    "INV_EXPECTED_PROJECTION_AFTER_ACTUAL_CALL"
                )
                assert [f.name for f in dataclasses.fields(result)] == expected["fields_order"]
                assert json.dumps(
                    _inv_plain(result), sort_keys=True, separators=(",", ":")
                ) == json.dumps(expected["fields"], sort_keys=True, separators=(",", ":")), (
                    "INV_HAND_FIELDS_AFTER_ACTUAL_CALL"
                )
                _inv_deep_immutable(result)
                assert len(result.logical_object_rows) + len(result.engine_object_rows) == len(
                    objects
                )
                assert sorted(
                    map(id, result.logical_object_rows + result.engine_object_rows)
                ) == sorted(map(id, objects)), "INV_RAW_PARTITION_IDENTITY"
                if original_indices:
                    for field, key in [
                        (result.logical_object_rows, "logical"),
                        (result.engine_object_rows, "engine"),
                    ]:
                        assert all(
                            row is objects[i]
                            for row, i in zip(
                                field, expected["original_row_identity_indices"][key], strict=True
                            )
                        )
                with pytest.raises(dataclasses.FrozenInstanceError):
                    result.logical_objects = ()
    assert len(matched) == expected["matcher_calls"], "INV_ACTUAL_MATCHER_COUNT"
    if expected["kind"] == "Projection":
        assert matched == [_inv_freeze(expected["fields"]["logical_objects"])], (
            "INV_ACTUAL_MATCHER_ARGUMENT"
        )
    assert not traps, "INV_GETTER_COERCION_ZERO"
    assert not attempts, "INV_IO_ZERO"
    assert _inv_input_fingerprint((objects, evidence)) == before, "INV_INPUT_UNCHANGED"
    return result


@pytest.mark.parametrize(
    "case", _INV_CASES, ids=[row["local_id"] for row in _INV_SELECTION["cases"]]
)
def test_private_supplied_inventory(case, monkeypatch):
    _inv_run_hand(case, monkeypatch)


def test_private_supplied_inventory_literal_audit():
    import hashlib
    from collections import Counter

    assert (
        hashlib.sha256(_INV_CORE_RAW.encode()).hexdigest()
        == "0050f3bb112d9ec4338f30ba88aa92ec52505a1d7f76d758241ad0c195e47cd1"
    )
    assert (
        hashlib.sha256(_INV_MANIFEST_RAW.encode()).hexdigest()
        == "0fe2e427ecd413f9b6dcd205c59ff849b2bc54ab46b9263e26f960ad1530d333"
    )
    assert len(_INV_CASES) == len(_INV_SELECTION["cases"]) == 151
    assert Counter(c["expected"]["kind"] for c in _INV_CASES) == {
        "Projection": 17,
        "ValueError": 91,
        "None": 43,
    }
    assert [row["local_id"] for row in _INV_SELECTION["cases"]] == [
        f"PRIVATE-INV{i:03d}" for i in range(1, 152)
    ]
    assert len({row["nodeid"] for row in _INV_SELECTION["cases"]}) == 151
    assert all(
        case["descriptive_label"] == row["descriptive_label"] and row["formal_ID"] is None
        for case, row in zip(_INV_CASES, _INV_SELECTION["cases"], strict=True)
    )
    for case, row in zip(_INV_CASES, _INV_SELECTION["cases"], strict=True):
        canonical = json.dumps(
            case, ensure_ascii=True, sort_keys=True, separators=(",", ":")
        ).encode("utf8")
        assert hashlib.sha256(canonical).hexdigest() == row["core_sha256"], (
            "INV_EXACT_SELECTED_ROW_CORE_HASH"
        )
    assert _INV_SELECTION["formal70_denominator4105_primary245_deferred10_unchanged"] is True
    assert (
        _INV_SELECTION["new_node_count"] == 153 and _INV_SELECTION["mutation_sites_selected"] == 0
    )


def test_private_supplied_inventory_order_and_immutability(monkeypatch):
    import random

    def reorder(value, mode, level=0):
        # Only reorder collections of rows/bundles; preserve cells and their ordinals.
        if mode == "identity":
            return value
        objects, evidence = value
        randomizer = random.Random(160016)

        def permute(rows):
            rows = list(rows)
            if mode == "reverse":
                rows.reverse()
            else:
                randomizer.shuffle(rows)
            return tuple(rows)

        return permute(objects), permute(
            tuple(
                (
                    owner,
                    permute(columns),
                    permute(indexes),
                    permute(tuple((name, permute(info)) for name, info in infos)),
                )
                for owner, columns, indexes, infos in evidence
            )
        )

    positives = [case for case in _INV_CASES if case["expected"]["kind"] == "Projection"]
    assert len(positives) == 17
    for case in positives:
        objects, evidence, traps = _inv_construct(case)
        assert not traps
        for mode in ("identity", "reverse", "seeded"):
            obj, ev = reorder((objects, evidence), mode)
            _inv_run_hand(case, monkeypatch, obj, ev, original_indices=False)


