def _cinv_sources():
    import base64
    import zlib

    return {
        name: zlib.decompress(base64.b85decode(payload))
        for name, payload in _CINV_COMPRESSED_SOURCES.items()
    }


def _cinv_pointer(value, pointer):
    for part in pointer.split("/")[1:]:
        part = part.replace("~1", "/").replace("~0", "~")
        value = value[int(part)] if type(value) is list else value[part]
    return value


_CINV_RAW_SOURCES = _cinv_sources()
_CINV_SOURCE_DATA = {name: json.loads(raw) for name, raw in _CINV_RAW_SOURCES.items()}
_CINV_APPROVAL = json.loads(_CINV_APPROVAL_RAW)
_CINV_RECORDS = _CINV_APPROVAL["immutable_source_records"]
_CINV_IDS = _CINV_APPROVAL["selected_private_local_IDs"]


def _cinv_json(value):
    return json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"))


def _cinv_fingerprint(value):
    if isinstance(value, tuple):
        return [type(value).__name__, [_cinv_fingerprint(x) for x in tuple.__iter__(value)]]
    if isinstance(value, list):
        return [type(value).__name__, [_cinv_fingerprint(x) for x in list.__iter__(value)]]
    if type(value) is dict:
        return ["dict", [[k, _cinv_fingerprint(v)] for k, v in value.items()]]
    if isinstance(value, str):
        return [type(value).__name__, str.__str__(value)]
    if type(value) is bytes:
        return ["bytes", value.hex()]
    if isinstance(value, int):
        return [type(value).__name__, int.__int__(value)]
    return [type(value).__name__, value]


def _cinv_decode_tag(value):
    if type(value) is dict and "exact_type" in value:
        assert set(value) == {"exact_type", "items"}, "CINV_HARNESS_TAG_FIELDS"
        items = [_cinv_decode_tag(x) for x in value["items"]]
        assert value["exact_type"] in ("tuple", "list"), "CINV_HARNESS_TAG_KIND"
        return tuple(items) if value["exact_type"] == "tuple" else items
    return value


def _cinv_prepare(program, review=False):
    import copy

    traps = []

    def trap(*args, **kwargs):
        traps.append("coercion/getter")
        raise AssertionError("CINV_ACTUAL_COERCION")

    class Text(str):
        __str__ = trap

    class Number(int):
        __int__ = trap
        __index__ = trap

    class Rows(list):
        __iter__ = trap

    class Cells(tuple):
        __iter__ = trap

    def construct(value, specification):
        name = specification["python_type"]
        if name == "bytes":
            return bytes.fromhex(specification["hex"])
        value = specification.get("value", value)
        constructors = {
            "exact_list": list,
            "exact_tuple": tuple,
            "str_subclass": Text,
            "int_subclass": Number,
            "list_subclass": Rows,
            "tuple_subclass": Cells,
        }
        assert name in constructors, "CINV_HARNESS_CONSTRUCTOR"
        return constructors[name](value)

    if review:
        budget = {
            "delivery": "construct_exact_budget",
            "values": {
                "max_rows": program["budget_construct"]["positional_args"][0],
                "max_text_bytes": program["budget_construct"]["positional_args"][1],
            },
        }
        call = {"entrypoint": "collector", "positional": ["connection", "budget"], "keywords": {}}
        connection = {"row_factory": None, "text_factory": "str"}
        queries = []
        for record in program["queries"]:
            faults = {}
            for source, target in (
                ("row_factory_set", "row_factory"),
                ("execute", "execute"),
                ("description", "description"),
                ("close", "close"),
            ):
                if record[source]["raise_token"] is not None:
                    faults[target] = record[source]["raise_token"]
            chunks = []
            for i, step in enumerate(record["fetchmany_steps"]):
                chunks.append(_cinv_decode_tag(step.get("result")))
                if step["raise_token"] is not None:
                    faults["fetchmany_" + str(i)] = step["raise_token"]
            queries.append(
                {
                    "SQL": record["SQL"],
                    "description": _cinv_decode_tag(record["description"]["value"]),
                    "chunks": chunks,
                    "faults": faults,
                }
            )
        definitions = {
            name: {"class": row["exact_class_ref"], "args": row["args"]}
            for name, row in program["exception_registry"].items()
        }
    else:
        budget = copy.deepcopy(program["budget"])
        call = copy.deepcopy(program["call"])
        connection = copy.deepcopy(program["connection"])
        queries = []
        for record in program["query_program"]:
            description = record["description"]
            if type(description) is list:
                description = tuple(tuple(x) if type(x) is list else x for x in description)
            chunks = [
                [tuple(row) if type(row) is list else row for row in chunk]
                if type(chunk) is list
                else chunk
                for chunk in record["chunks"]
            ]
            queries.append(
                {
                    "SQL": record["SQL"],
                    "description": description,
                    "chunks": chunks,
                    "faults": copy.deepcopy(record["faults"]),
                }
            )
        definitions = _CINV_SOURCE_DATA[_CINV_APPROVAL["sources"]["main"]["path"]]["exceptions"]
        overrides = {
            item["path"]: item["constructor"] for item in program.get("builder_overrides", [])
        }

        def replace(value, parts, specification):
            if not parts:
                return construct(value, specification)
            key = int(parts[0]) if isinstance(value, (list, tuple)) else parts[0]
            if type(value) is tuple:
                output = list(value)
                output[key] = replace(output[key], parts[1:], specification)
                return tuple(output)
            value[key] = replace(value[key], parts[1:], specification)
            return value

        graph = {"query_program": queries, "budget": budget}
        for pointer, specification in overrides.items():
            graph = replace(graph, pointer.split("/")[1:], specification)
        queries, budget = graph["query_program"], graph["budget"]
    return call, budget, connection, queries, definitions, traps


class _CinvCursor:
    def __init__(self, connection, index):
        self.connection = connection
        self.index = index
        self.record = connection.queries[index]
        self._row_factory = connection.row_factory
        self.fetch_index = 0
        self.close_attempts = 0

    def fault(self, name):
        symbol = self.record["faults"].get(name)
        if symbol is not None:
            self.connection.raised.append(symbol)
            raise self.connection.exceptions[symbol]

    @property
    def row_factory(self):
        return self._row_factory

    @row_factory.setter
    def row_factory(self, value):
        self.connection.events.append((self.index, "row_factory", value))
        assert value is None, "CINV_OWN_CURSOR_FACTORY_NONE"
        self.fault("row_factory")
        self._row_factory = value

    def execute(self, sql):
        self.connection.events.append((self.index, "execute", sql))
        assert sql == self.record["SQL"], "CINV_ACTUAL_SQL_ORDER"
        self.fault("execute")
        return self

    @property
    def description(self):
        self.connection.events.append((self.index, "description"))
        self.fault("description")
        return self.record["description"]

    def fetchmany(self, size):
        self.connection.events.append((self.index, "fetchmany", size))
        self.connection.fetches[self.index].append(size)
        step = self.fetch_index
        self.fetch_index += 1
        self.fault("fetchmany_" + str(step))
        assert step < len(self.record["chunks"]), "CINV_FETCH_PAST_COMPLETE_PROGRAM"
        result = self.record["chunks"][step]
        if type(result) is list:
            self.connection.returned_rows += len(result)
        return result

    def close(self):
        self.connection.events.append((self.index, "close"))
        self.close_attempts += 1
        assert self.close_attempts == 1, "CINV_CLOSE_ONCE"
        self.fault("close")
        self.connection.closed += 1


class _CinvConnection:
    def __init__(self, queries, exceptions, configuration):
        import sqlite3

        self.queries = queries
        self.exceptions = exceptions
        self.events = []
        self.cursors = []
        self.fetches = []
        self.raised = []
        self.closed = 0
        self.returned_rows = 0
        self.index = 0
        self.row_factory = (
            sqlite3.Row if configuration.get("row_factory") == "sqlite3.Row" else None
        )
        self.text_factory = str
        self.in_transaction = True
        self.isolation_level = "CALLER_OWNED"
        self.handlers = (object(), object(), object())
        self.timeout = object()
        self.locked = True

    def __setattr__(self, name, value):
        assert not self.__dict__.get("locked", False) or name not in {
            "row_factory",
            "text_factory",
            "in_transaction",
            "isolation_level",
            "handlers",
            "timeout",
        }, "CINV_CONNECTION_SETTING_MUTATION"
        object.__setattr__(self, name, value)

    @property
    def cursor(self):
        index = self.index
        assert index < len(self.queries), "CINV_CURSOR_PAST_COMPLETE_PROGRAM"
        self.events.append((index, "cursor_access"))
        self.fetches.append([])
        record = self.queries[index]
        token = record["faults"].get("cursor_access")
        if token:
            self.raised.append(token)
            raise self.exceptions[token]
        return self._cursor

    def _cursor(self):
        index = self.index
        self.events.append((index, "cursor_call"))
        token = self.queries[index]["faults"].get("cursor_call")
        if token:
            self.raised.append(token)
            raise self.exceptions[token]
        cursor = _CinvCursor(self, index)
        self.cursors.append(cursor)
        self.index += 1
        return cursor

    def __getattribute__(self, name):
        if name in {
            "close",
            "commit",
            "rollback",
            "execute",
            "executescript",
            "executemany",
            "interrupt",
            "set_trace_callback",
            "set_progress_handler",
            "set_authorizer",
        }:
            raise AssertionError("CINV_CONNECTION_FORBIDDEN_EFFECT:" + name)
        return object.__getattribute__(self, name)

    def snapshot(self):
        return (
            self.row_factory,
            self.text_factory,
            self.in_transaction,
            self.isolation_level,
            self.handlers,
            self.timeout,
        )


def _cinv_run(program, expected, monkeypatch, *, review=False, state_fault=None):
    import builtins
    import ctypes
    import dataclasses
    import io
    import multiprocessing
    import os
    import socket
    import sqlite3
    import subprocess
    import sys
    import threading
    from contextlib import ExitStack
    from pathlib import Path
    from unittest.mock import patch

    from recoryn import schema

    call, specification, configuration, queries, definitions, traps = _cinv_prepare(program, review)
    types = {
        "sqlite3.OperationalError": sqlite3.OperationalError,
        "builtins.AttributeError": AttributeError,
        "builtins.TypeError": TypeError,
        "builtins.RuntimeError": RuntimeError,
        "builtins.LookupError": LookupError,
    }
    exceptions = {name: types[row["class"]](*row["args"]) for name, row in definitions.items()}
    connection = _CinvConnection(queries, exceptions, configuration)
    snapshot = connection.snapshot()
    input_before = _cinv_fingerprint((queries, specification))
    original_program = _cinv_json(program)
    counts = {}
    project_args = []
    matcher_args = []
    project_returns = []
    completed_usage = []
    matcher_returns = []
    actual_errors = []
    attempts = []
    source = Path(schema.__file__).resolve()
    names = (
        "_collect_supplied_inventory",
        "_inventory_read_rows",
        "_project_supplied_inventory",
        "_current_profile_candidate",
        "__post_init__",
    )
    functions = {
        name: inspect.unwrap(
            getattr(schema._InventoryReadBudget, name)
            if name == "__post_init__"
            else getattr(schema, name)
        )
        for name in names
    }
    codes = {fn.__code__: name for name, fn in functions.items()}
    for fn in functions.values():
        assert (
            fn.__globals__ is schema.__dict__ and Path(fn.__code__.co_filename).resolve() == source
        )

    def observe(frame, event, arg):
        name = codes.get(frame.f_code)
        if name is not None:
            assert frame.f_globals is schema.__dict__, "CINV_ACTUAL_CANONICAL_GLOBALS"
            if event == "call":
                counts[name] = counts.get(name, 0) + 1
                if name == "_project_supplied_inventory":
                    project_args.append((frame.f_locals["objects"], frame.f_locals["evidence"]))
                elif name == "_current_profile_candidate":
                    matcher_args.append(frame.f_locals["logical_objects"])
            elif event == "return":
                if name == "_inventory_read_rows" and arg is not None:
                    completed_usage.append(tuple(frame.f_locals["usage"]))
                if name == "_project_supplied_inventory":
                    project_returns.append(arg)
                elif name == "_current_profile_candidate":
                    matcher_returns.append(arg)
            elif event == "exception":
                actual_errors.append((name, arg[1]))
        return observe

    delivery = specification["delivery"]
    values = specification["values"]
    special_budget = None
    if delivery == "budget_subclass":

        class SubBudget(schema._InventoryReadBudget):
            pass

        special_budget = object.__new__(SubBudget)
    elif delivery == "bypass_constructor_exact_budget":
        special_budget = object.__new__(schema._InventoryReadBudget)
    if special_budget is not None:
        for name, value in values.items():
            object.__setattr__(special_budget, name, value)

    def forbidden(*args, **kwargs):
        attempts.append("I/O")
        raise AssertionError("CINV_ACTUAL_PRODUCT_IO")

    original_catalog = schema._CP_PROFILES
    result = None
    error = None
    oldtrace = sys.gettrace()
    prior_locals = {}
    initial_locals = {}
    forwarded = {"call": 0, "line": 0, "return": 0, "exception": 0}
    callback_errors = []
    relaying = True

    def relay(frame, event, arg):
        previous = oldtrace if event == "call" else prior_locals.get(frame)
        continuation = None
        if previous is not None:
            frame.f_trace = None if event == "call" else previous
            try:
                continuation = previous(frame, event, arg)
            except BaseException as callback_error:
                callback_errors.append(callback_error)
                prior_locals.pop(frame, None)
                raise
            if relaying and sys.gettrace() is not relay:
                sys.settrace(relay)
            forwarded[event] = forwarded.get(event, 0) + 1
            if continuation is None:
                # CPython keeps a local callback which returns None; an explicit
                # frame.f_trace assignment by that callback still takes effect.
                continuation = frame.f_trace
        if not relaying:
            if frame in initial_locals:
                initial_locals[frame] = continuation
            prior_locals.pop(frame, None)
            frame.f_trace = continuation
            return continuation
        prior_locals[frame] = continuation
        try:
            observe(frame, event, arg)
        finally:
            if event == "return":
                prior_locals.pop(frame, None)
                frame.f_trace = continuation
        if event == "return":
            return continuation
        frame.f_trace = relay
        return relay

    with monkeypatch.context(), ExitStack() as stack:
        targets = [
            (builtins, "open"),
            (io, "open"),
            (os, "open"),
            (os, "system"),
            (sqlite3, "connect"),
            (socket, "socket"),
            (socket, "getaddrinfo"),
            (threading.Thread, "start"),
            (subprocess, "Popen"),
            (multiprocessing.process.BaseProcess, "start"),
        ]
        targets.extend(
            (ctypes, name)
            for name in ("CDLL", "PyDLL", "WinDLL", "OleDLL")
            if hasattr(ctypes, name)
        )
        for owner, name in targets:
            stack.enter_context(patch.object(owner, name, forbidden))
        traps.clear()
        if state_fault is not None:
            assert type(original_catalog) is tuple and len(original_catalog) == 30
            schema._CP_PROFILES = original_catalog[:-1]
        if oldtrace is not None:
            active_frame = sys._getframe()
            while active_frame is not None:
                initial_locals[active_frame] = active_frame.f_trace
                prior_locals[active_frame] = active_frame.f_trace
                active_frame.f_trace = relay
                active_frame = active_frame.f_back
        sys.settrace(observe if oldtrace is None else relay)
        try:
            if call["entrypoint"] == "budget_constructor":
                tokens = values
                result = schema._InventoryReadBudget(
                    *[tokens[x] for x in call["positional"]],
                    **{k: tokens[v] for k, v in call["keywords"].items()},
                )
            else:
                assert call["entrypoint"] in ("collector", "_collect_supplied_inventory")
                if delivery == "construct_exact_budget":
                    budget = schema._InventoryReadBudget(
                        values["max_rows"], values["max_text_bytes"]
                    )
                elif delivery == "None":
                    budget = None
                elif delivery == "plain_mapping":
                    budget = dict(values)
                else:
                    assert special_budget is not None, "CINV_HARNESS_BUDGET_DELIVERY"
                    budget = special_budget
                tokens = {"connection": connection, "budget": budget, "extra": object()}
                result = schema._collect_supplied_inventory(
                    *[tokens[x] for x in call["positional"]],
                    **{k: tokens[v] for k, v in call["keywords"].items()},
                )
        except BaseException as caught:
            error = caught
        finally:
            relaying = False
            sys.settrace(oldtrace)
            for traced_frame, prior_local in tuple(prior_locals.items()):
                traced_frame.f_trace = prior_local
            for traced_frame, prior_local in tuple(initial_locals.items()):
                traced_frame.f_trace = prior_locals.get(traced_frame, prior_local)
            prior_locals.clear()
            initial_locals.clear()
            schema._CP_PROFILES = original_catalog
    if callback_errors:
        raise callback_errors[0]
    assert sys.gettrace() is oldtrace, "CINV_PRIOR_TRACE_IDENTITY_RESTORED"
    assert not prior_locals and not initial_locals, "CINV_PRIOR_LOCAL_TRACE_REFERENCES_RELEASED"
    assert schema._CP_PROFILES is original_catalog, "CINV_CATALOG_IDENTITY_RESTORE"
    assert not traps and not attempts, "CINV_NO_COERCION_OR_PRODUCT_IO"
    assert connection.snapshot() == snapshot, "CINV_CALLER_STATE_PRESERVED"
    assert _cinv_fingerprint((queries, specification)) == input_before, "CINV_INPUT_UNCHANGED"
    assert _cinv_json(program) == original_program, "CINV_SOURCE_LITERAL_UNCHANGED"
    assert all(cursor.close_attempts == 1 for cursor in connection.cursors), (
        "CINV_EVERY_OWN_CURSOR_CLOSE_ONCE"
    )
    assert counts.get("_project_supplied_inventory", 0) == expected.get("project_calls", 0), (
        "CINV_REAL_PROJECT_CALL_COUNT"
    )
    if "matcher_calls" in expected:
        assert counts.get("_current_profile_candidate", 0) == expected["matcher_calls"], (
            "CINV_REAL_MATCHER_CALL_COUNT"
        )
    count_fields = {
        "cursor_created": len(connection.cursors),
        "cursor_opened": len(connection.cursors),
        "all_cursors_created": len(connection.cursors),
        "cursor_close_attempts": sum(cursor.close_attempts for cursor in connection.cursors),
        "all_cursor_close_attempts_successful": connection.closed,
        "cursor_close_success": connection.closed,
        "cursor_call_attempts": sum(event[1] == "cursor_call" for event in connection.events),
        "fetchmany_calls": sum(map(len, connection.fetches)),
        "execute_calls": sum(event[1] == "execute" for event in connection.events),
        "description_gets": sum(event[1] == "description" for event in connection.events),
        "cursor_row_factory_None_set": sum(
            event[1] == "row_factory" and event[2] is None for event in connection.events
        ),
        "observed_returned_rows_until_failure": connection.returned_rows,
    }
    for key, actual in count_fields.items():
        if type(expected.get(key)) is int:
            assert actual == expected[key], ("CINV_ACTUAL_EVENT_COUNT", key, actual, expected[key])
    requests = expected.get(
        "literal_fetch_requests_through_failure",
        expected.get("literal_fetch_requests", expected.get("fetchmany_sizes_by_query")),
    )
    if requests is not None:
        assert connection.fetches == requests, "CINV_ACTUAL_FETCH_VECTOR"
    if expected.get("normal_return") and "complete_hand_arithmetic" in expected:
        costs = expected["complete_hand_arithmetic"]["query_costs"]
        fetch_key = (
            "complete_normal_fetch_requests"
            if "query_count" in expected["complete_hand_arithmetic"]
            else "fetchmany_requests_if_this_normal_trace_completes"
        )
        assert all(fetch_key in row for row in costs), "CINV_HARNESS_HAND_COST_FORMAT"
        assert connection.fetches == [row[fetch_key] for row in costs], (
            "CINV_COMPLETE_HAND_FETCH_VECTOR"
        )
        assert completed_usage == [
            (row["cumulative_rows"], row["cumulative_text_bytes"]) for row in costs
        ], "CINV_COMPLETE_HAND_CUMULATIVE_COSTS"
    for key in ("query_order", "queries_SQL"):
        if key in expected:
            assert [event[2] for event in connection.events if event[1] == "execute"] == expected[
                key
            ]
    if "observed_raised_tokens_in_order" in expected:
        assert connection.raised == expected["observed_raised_tokens_in_order"]
    if "third_end_chunk_reached" in expected:
        assert (connection.cursors[-1].fetch_index >= 3) is expected["third_end_chunk_reached"]
    if project_args and expected.get("actual_project_input") is not None:
        objects, evidence = project_args[0]
        assert _cinv_json(_inv_plain({"objects": objects, "evidence": evidence})) == _cinv_json(
            expected["actual_project_input"]
        ), "CINV_ACTUAL_PROJECT_ARGUMENTS"
    if expected.get("normal_return"):
        assert error is None, ("CINV_UNEXPECTED_ACTUAL_ERROR", type(error).__name__, str(error))
        outcome = expected.get("outcome")
        if outcome is None:
            outcome = {
                "kind": "Projection",
                "fields_order": expected["fields_order"],
                "fields": expected["fields"],
            }
        if outcome["kind"] == "Budget":
            assert type(result) is schema._InventoryReadBudget
            assert [result.max_rows, result.max_text_bytes] == outcome["values"]
            assert counts.get("__post_init__", 0) == 1 and not connection.events
            assert result.__dataclass_params__.frozen and not result.__dataclass_params__.repr
        else:
            assert project_returns and result is project_returns[-1], (
                "CINV_ACTUAL_DELEGATE_RETURN_IDENTITY"
            )
            if outcome["kind"] == "None":
                assert result is None
            else:
                assert type(result) is schema._SuppliedInventoryProjection, (
                    "CINV_EXACT_RESULT_CLASS"
                )
                assert [field.name for field in dataclasses.fields(result)] == outcome[
                    "fields_order"
                ]
                assert _cinv_json(_inv_plain(result)) == _cinv_json(outcome["fields"]), (
                    "CINV_ORIGINAL_RESULT5_FIELDS"
                )
                _inv_deep_immutable(result)
                if matcher_args:
                    assert _cinv_json(_inv_plain(matcher_args[-1])) == _cinv_json(
                        outcome["fields"]["logical_objects"]
                    )
                    assert result.profile_candidate is matcher_returns[-1], (
                        "CINV_ACTUAL_MATCHER_RETURN_IDENTITY"
                    )
    else:
        assert error is not None, "CINV_EXPECTED_ERROR_AFTER_ACTUAL_CALL"
        exc = expected["exception"]
        if "identity" in exc or "identity_token" in exc:
            symbol = exc.get("identity", exc.get("identity_token"))
            assert error is exceptions[symbol], "CINV_ORIGINAL_EXCEPTION_IDENTITY"
        elif "closed_reason" in exc:
            assert type(error) is schema._InventoryCollectionError, "CINV_EXACT_COLLECTION_ERROR"
            assert error.args == (exc["closed_reason"],), "CINV_CLOSED_REASON_AFTER_ACTUAL_CALL"
        elif "TypeError" in exc.get("class", ""):
            assert type(error) is TypeError
            assert counts.get("_collect_supplied_inventory", 0) == 0, "CINV_BINDING_BODY_ZERO"
        else:
            expected_type = RuntimeError if "RuntimeError" in exc.get("class", "") else ValueError
            assert type(error) is expected_type
            assert error.args == tuple(exc["args"]), "CINV_CLOSED_ORIGINAL_ERROR"
        if state_fault is not None:
            matcher_errors = [
                value for name, value in actual_errors if name == "_current_profile_candidate"
            ]
            assert matcher_errors and error is matcher_errors[-1], (
                "CINV_ACTUAL_MATCHER_EXCEPTION_IDENTITY"
            )
    audit_path = os.environ.get("CINV_EVENT_AUDIT")
    if audit_path:
        with open(audit_path, "a", encoding="utf8") as stream:
            stream.write(
                json.dumps(
                    {
                        "counts": counts,
                        "cursor_created": len(connection.cursors),
                        "close": sum(cursor.close_attempts for cursor in connection.cursors),
                        "fetch": connection.fetches,
                        "IO": attempts,
                        "source": str(source),
                        "exception": type(error).__name__ if error is not None else None,
                        "prior_trace_type": type(oldtrace).__module__
                        + "."
                        + type(oldtrace).__name__,
                        "prior_trace_id": id(oldtrace),
                        "restored_trace_id": id(sys.gettrace()),
                        "prior_trace_identity_restored": sys.gettrace() is oldtrace,
                        "prior_callbacks_forwarded": forwarded,
                        "prior_local_references_after_cleanup": len(prior_locals),
                    }
                )
                + "\n"
            )


def _cinv_adapter(metadata):
    import copy

    record = _cinv_pointer(
        _CINV_SOURCE_DATA[metadata["source_file"]], metadata["source_JSON_pointer"]
    )
    kind = metadata["adapter_kind"]
    if kind == "hand_candidate_v1":
        return (
            copy.deepcopy(record["counterpart"]["input"]),
            copy.deepcopy(record["input"]),
            copy.deepcopy(record["expected"]),
            False,
            None,
        )
    if kind == "FIX2_wrapper_candidate_v1":
        return (
            copy.deepcopy(record["counterpart"]["api_program"]),
            copy.deepcopy(record["input"]["api_program"]),
            copy.deepcopy(record["expected"]),
            False,
            copy.deepcopy(record["input"]["test_only_state_fault"]),
        )
    if kind == "H01_single_program_v1":
        budget = record["budget"]
        program = {
            "call": record["call"],
            "budget": {
                "delivery": "construct_exact_budget",
                "values": {
                    "max_rows": budget["max_rows"],
                    "max_text_bytes": budget["max_text_bytes"],
                },
            },
            "connection": {"row_factory": None, "text_factory": "str"},
            "query_program": record["query_program"],
            "builder_overrides": [],
        }
        expected = copy.deepcopy(record["expected"])
        return None, copy.deepcopy(program), expected, False, None
    assert kind == "review_program_and_pair_v1", "CINV_HARNESS_ADAPTER_KIND"
    source = _CINV_SOURCE_DATA[metadata["source_file"]]
    control = source["programs"]["shared_empty_equality_control"]
    return (
        copy.deepcopy(control["program"]),
        copy.deepcopy(record["program"]),
        copy.deepcopy(record["oracle"]),
        True,
        None,
    )


def _cinv_control_expected(program, review=False):
    if review:
        # The separate approved empty semantic binding is embedded verbatim.
        expected = dict(_CINV_EMPTY_EXPECTED)
        source = _CINV_SOURCE_DATA[_CINV_APPROVAL["sources"]["review"]["path"]]
        expected.update(source["programs"]["shared_empty_equality_control"]["oracle"])
        expected["actual_project_input"] = {"objects": [], "evidence": []}
        expected["normal_return"] = True
        expected["project_calls"] = expected["matcher_calls"] = 1
        expected["outcome"] = {
            "kind": "Projection",
            "fields_order": expected["fields_order"],
            "fields": expected["fields"],
        }
        return expected
    call = program["call"]
    if call["entrypoint"] == "budget_constructor":
        values = program["budget"]["values"]
        return {
            "normal_return": True,
            "project_calls": 0,
            "matcher_calls": 0,
            "outcome": {"kind": "Budget", "values": [values["max_rows"], values["max_text_bytes"]]},
        }
    return {
        "normal_return": True,
        "project_calls": 1,
        "matcher_calls": program["expected_matcher_calls"],
        "outcome": program["expected_output"],
        "actual_project_input": program["expected_project_input"],
    }


@pytest.mark.parametrize("metadata", _CINV_RECORDS, ids=_CINV_IDS)
def test_private_supplied_inventory_collection(metadata, monkeypatch):
    import copy

    before = _cinv_json(metadata)
    counterpart, program, expected, review, state = _cinv_adapter(metadata)
    if counterpart is not None:
        record = _cinv_pointer(
            _CINV_SOURCE_DATA[metadata["source_file"]], metadata["source_JSON_pointer"]
        )
        control_expected = record.get(
            "counterpart_expected", _cinv_control_expected(counterpart, review)
        )
        _cinv_run(counterpart, control_expected, monkeypatch, review=review)
    expected = copy.deepcopy(expected)
    if review:
        exc = expected["exception"]
        if "exact_class_ref" in exc:
            exc["class"] = exc["exact_class_ref"]
    _cinv_run(program, expected, monkeypatch, review=review, state_fault=state)
    assert _cinv_json(metadata) == before


def test_private_supplied_inventory_collection_literal_audit():
    assert (
        hashlib.sha256(_CINV_APPROVAL_RAW.encode("utf8")).hexdigest()
        == "b373ae3a07835fc045343a4b1402a39bd04f3a3e47287d4bffbc06584e557a7c"
    )
    assert _CINV_IDS == ["CINV" + str(i).zfill(3) for i in range(1, 120)]
    assert len(_CINV_RECORDS) == len(set(_CINV_IDS)) == 119
    for name, reference in _CINV_APPROVAL["sources"].items():
        del name
        assert (
            hashlib.sha256(_CINV_RAW_SOURCES[reference["path"]]).hexdigest()
            == reference["raw_sha256"]
        )
    for identity, metadata in zip(_CINV_IDS, _CINV_RECORDS, strict=True):
        assert metadata["proposed_private_local_ID"] == identity
        record = _cinv_pointer(
            _CINV_SOURCE_DATA[metadata["source_file"]], metadata["source_JSON_pointer"]
        )
        assert (
            hashlib.sha256(_cinv_json(record).encode("utf8")).hexdigest()
            == metadata["source_record_canonical_sha256"]
        )
        for auxiliary in metadata["auxiliary_source_records"]:
            value = _cinv_pointer(
                _CINV_SOURCE_DATA[metadata["source_file"]], auxiliary["source_JSON_pointer"]
            )
            assert (
                hashlib.sha256(_cinv_json(value).encode("utf8")).hexdigest()
                == auxiliary["canonical_sha256"]
            )
